Json read(const char* file){Json j;std::ifstream f(file);f>>j;return j;}
int main(){addressData()=read("assets/address-rules.json");subdivisionData()=read("assets/subdivision-names.json");assert(regionLabel("US",0)=="Штат"&&postalLabel("US",0)=="ZIP-код");assert(resolveRegion("US","Нью-Йорк")=="NY");assert(resolveRegion("US","New York")=="NY");assert(resolveRegion("US","US-NY")=="NY");assert(regionName("US","NY",0)=="Нью-Йорк");assert(resolveRegion("UA","Николаевская область")=="48");assert(resolveRegion("CA","Ontario")=="ON");assert(usesPostal("US")&&usesPostal("UA")&&!usesPostal("AE")&&!usesPostal("HK"));assert(validPostal("US","10001")&&validPostal("US",normalizePostal("US","100011234"))&&!validPostal("US","123"));assert(validPostal("CA",normalizePostal("CA","k1a0b1")));assert(validPostal("UA","54001")&&!validPostal("UA","540001"));assert(validPostal("RU","101000")&&validPostal("GB","SW1A 1AA"));assert(validPostal("JP",normalizePostal("JP","1000001")));State s;s.location.valid=true;s.location.country="US";s.location.postal="10001";s.location.region="NY";auto restored=decode(encode(s));assert(restored.location.postal=="10001");auto old=encode(s);old["location"].erase("postal");assert(decode(old).location.postal.empty());auto zones=read("assets/zones.json");assert(defaultZone("UA",zones["countries"]["UA"])=="Europe/Kyiv");Location sim;sim.valid=true;sim.country="UA";sim.city="Simferopol";sim.zone="Europe/Simferopol";Location nik=sim;nik.city="Mykolaiv";nik.zone="Europe/Kyiv";s.countries={{"UA","Ukraine",1,true,true,sim.zone,sim.city}};s.regions={{sim,{},0,1}};replaceCountryPlace(s,0,nik);assert(s.regions.size()==1&&s.regions[0].location.city=="Mykolaiv"&&s.regions[0].origin==1);s.countries[0].zone=sim.zone;s.countries[0].clockCity=sim.city;s.regions={{sim,{},0,2}};replaceCountryPlace(s,0,nik);assert(s.regions.size()==2&&s.regions[0].origin==2);assert(decode(encode(s)).regions[0].origin==2);s.regions={{sim,{},0,0},{nik,{},0,0}};assert(pruneLegacyDefaults(s,zones["countries"]));assert(s.regions.size()==1&&s.regions[0].location.city==nik.city);std::cout<<"Country-specific labels, translated regions, postal formats, save migration and generated city replacement: PASS\n";}
